#define CATALOG_MAGIC 0x43415431u
#define TABLE_MAGIC   0x54424C31u
#define ROW_MAGIC     0x524F5731u
#define MAX_TABLES 128
#define MAX_RESULT_ROWS 4096
#define VALUE_LEN 240
#define NAME_LEN 64
#define MAX_COLS 16

typedef struct { uint32_t magic; int32_t first_table; } CatalogPage;
typedef struct {
    uint32_t magic;
    int32_t next_table, first_row, last_row, row_count, column_count;
    char name[NAME_LEN];
    char columns[MAX_COLS][NAME_LEN];
} TablePage;
typedef struct { uint32_t magic; int32_t table_page, next_row; char values[MAX_COLS][VALUE_LEN]; } RowPage;
typedef struct { int page_id; char values[MAX_COLS][VALUE_LEN]; } ResultRow;

_Static_assert(sizeof(CatalogPage) <= PAGE_SIZE, "catalog page too large");
_Static_assert(sizeof(TablePage) <= PAGE_SIZE, "table page too large");
_Static_assert(sizeof(RowPage) <= PAGE_SIZE, "row page too large");

static int active_txn = 0;
static char database_path[512] = "cyberdb.db";

static int eq(const char *a,const char *b){while(*a&&*b){if(toupper((unsigned char)*a)!=toupper((unsigned char)*b))return 0;a++;b++;}return *a==0&&*b==0;}
static int is_identifier(const char*s){if(!s||!(isalpha((unsigned char)s[0])||s[0]=='_'))return 0;for(int i=1;s[i];i++)if(!(isalnum((unsigned char)s[i])||s[i]=='_'))return 0;return 1;}
static int is_operator(const char*s){return !strcmp(s,"=")||!strcmp(s,"!=")||!strcmp(s,"<>")||!strcmp(s,"<")||!strcmp(s,">")||!strcmp(s,"<=")||!strcmp(s,">=");}
static int appendf(char*out,int cap,int *used,const char*fmt,...){if(*used>=cap)return -1;va_list ap;va_start(ap,fmt);int n=vsnprintf(out+*used,(size_t)(cap-*used),fmt,ap);va_end(ap);if(n<0||n>=cap-*used)return -1;*used+=n;return 0;}
static int fail(char*out,int cap,const char*message){snprintf(out,(size_t)cap,"ERR %s\nEND\n",message);return -1;}
static int read_page_copy(int id,void*dst,size_t size){char*p=buffer_get_page(id);if(!p)return -1;memcpy(dst,p,size);buffer_unpin(id);return 0;}
static int get_catalog(CatalogPage*out){if(read_page_copy(0,out,sizeof *out)!=0)return -1;return out->magic==CATALOG_MAGIC?0:-1;}
static int get_table(int id,TablePage*out){if(read_page_copy(id,out,sizeof *out)!=0)return -1;return out->magic==TABLE_MAGIC?0:-1;}
static int table_find(const char*name,int*page_id,TablePage*out){CatalogPage c;if(get_catalog(&c)!=0)return -1;int id=c.first_table,guard=0;while(id>=0&&guard++<MAX_TABLES){TablePage t;if(get_table(id,&t)!=0)return -1;if(eq(t.name,name)){if(page_id)*page_id=id;if(out)*out=t;return 0;}id=t.next_table;}return -1;}
static int column_index(const TablePage*t,const char*name){for(int i=0;i<t->column_count;i++)if(eq(t->columns[i],name))return i;return -1;}
static int allocate_page(int*id,char**data){*id=storage_alloc_page();if(*id<0)return -1;*data=buffer_get_page(*id);if(!*data)return -1;memset(*data,0,PAGE_SIZE);return 0;}
static int parse_where_tokens(char tok[][TOKEN_LEN],int n,int*i,int*enabled,char*column,char*op,char*value){*enabled=0;if(*i>=n||!eq(tok[*i],"WHERE"))return 0;(*i)++;if(*i>=n||!is_identifier(tok[*i]))return -1;snprintf(column,TOKEN_LEN,"%s",tok[(*i)++]);if(*i>=n||!is_operator(tok[*i]))return -1;snprintf(op,3,"%s",tok[(*i)++]);if(*i>=n||eq(tok[*i],";")||eq(tok[*i],"ORDER"))return -1;snprintf(value,TOKEN_LEN,"%s",tok[(*i)++]);*enabled=1;return 0;}
static int compare_values(const char*a,const char*op,const char*b){char*ea=NULL,*eb=NULL;double da=strtod(a,&ea),db=strtod(b,&eb);int numeric=ea&&eb&&ea!=a&&eb!=b&&*ea=='\0'&&*eb=='\0';int c;if(numeric)c=da<db?-1:da>db?1:0;else c=strcmp(a,b);if(!strcmp(op,"="))return c==0;if(!strcmp(op,"!=")||!strcmp(op,"<>"))return c!=0;if(!strcmp(op,"<"))return c<0;if(!strcmp(op,">"))return c>0;if(!strcmp(op,"<="))return c<=0;if(!strcmp(op,">="))return c>=0;return 0;}
static int row_matches(const TablePage*t,const RowPage*r,int enabled,const char*col,const char*op,const char*value){if(!enabled)return 1;int ci=column_index(t,col);if(ci<0)return 0;return compare_values(r->values[ci],op,value);}
static int next_statement_end(char tok[][TOKEN_LEN],int n){return n>0&&eq(tok[n-1],";")?n-1:n;}

static int create_table(char tok[][TOKEN_LEN],int n,char*err,size_t errcap){int end=next_statement_end(tok,n);if(end<5||!eq(tok[0],"CREATE")||!eq(tok[1],"TABLE")||!is_identifier(tok[2])||!eq(tok[3],"(")){snprintf(err,errcap,"syntax: CREATE TABLE name (column type, ...)");return -1;}if(table_find(tok[2],NULL,NULL)==0){snprintf(err,errcap,"table already exists");return -1;}char cols[MAX_COLS][NAME_LEN];int count=0,i=4;
 while(i<end&&!eq(tok[i],")")){if(count>=MAX_COLS||!is_identifier(tok[i])){snprintf(err,errcap,"invalid or too many column names (maximum 16)");return -1;}for(int k=0;k<count;k++)if(eq(cols[k],tok[i])){snprintf(err,errcap,"duplicate column name");return -1;}snprintf(cols[count++],NAME_LEN,"%s",tok[i++]);int depth=0;while(i<end){if(eq(tok[i],"(")){depth++;i++;continue;}if(eq(tok[i],")")){if(depth==0)break;depth--;i++;continue;}if(eq(tok[i],",")&&depth==0)break;i++;}if(i<end&&eq(tok[i],","))i++;else break;}
 if(count==0||i>=end||!eq(tok[i],")")||i+1!=end){snprintf(err,errcap,"malformed CREATE TABLE column list");return -1;}
 CatalogPage cat;if(get_catalog(&cat)!=0){snprintf(err,errcap,"catalog page is corrupt");return -1;}int new_id;char*raw;if(allocate_page(&new_id,&raw)!=0){snprintf(err,errcap,"could not allocate table page");return -1;}TablePage*t=(TablePage*)raw;t->magic=TABLE_MAGIC;t->next_table=cat.first_table;t->first_row=-1;t->last_row=-1;t->row_count=0;t->column_count=count;snprintf(t->name,sizeof t->name,"%.63s",tok[2]);for(int k=0;k<count;k++)snprintf(t->columns[k],NAME_LEN,"%.63s",cols[k]);buffer_mark_dirty(new_id);buffer_unpin(new_id);
 raw=buffer_get_page(0);if(!raw){snprintf(err,errcap,"could not load catalog page");return -1;}((CatalogPage*)raw)->first_table=new_id;buffer_mark_dirty(0);buffer_unpin(0);return 0;}

static int insert_row(char tok[][TOKEN_LEN],int n,char*err,size_t errcap){int end=next_statement_end(tok,n),i=0;if(end<6||!eq(tok[i++],"INSERT")||!eq(tok[i++],"INTO")||i>=end||!is_identifier(tok[i])){snprintf(err,errcap,"syntax: INSERT INTO table [(columns)] VALUES (values)");return -1;}char table_name[TOKEN_LEN];snprintf(table_name,sizeof table_name,"%s",tok[i++]);int tid;TablePage t;if(table_find(table_name,&tid,&t)!=0){snprintf(err,errcap,"table does not exist");return -1;}int mapping[MAX_COLS],input_count=0;for(int k=0;k<MAX_COLS;k++)mapping[k]=k;
 if(i<end&&eq(tok[i],"(")){i++;input_count=0;while(i<end&&!eq(tok[i],")")){if(!is_identifier(tok[i])||input_count>=MAX_COLS){snprintf(err,errcap,"invalid INSERT column list");return -1;}int ci=column_index(&t,tok[i]);if(ci<0){snprintf(err,errcap,"unknown INSERT column");return -1;}for(int k=0;k<input_count;k++)if(mapping[k]==ci){snprintf(err,errcap,"duplicate INSERT column");return -1;}mapping[input_count++]=ci;i++;if(eq(tok[i],",")){i++;continue;}break;}if(i>=end||!eq(tok[i++],")")){snprintf(err,errcap,"missing ) in INSERT column list");return -1;}}
 else {input_count=t.column_count;for(int k=0;k<input_count;k++)mapping[k]=k;}
 if(i>=end||!eq(tok[i++],"VALUES")||i>=end||!eq(tok[i++],"(")){snprintf(err,errcap,"expected VALUES (");return -1;}char vals[MAX_COLS][VALUE_LEN];memset(vals,0,sizeof vals);int value_count=0;while(i<end&&!eq(tok[i],")")){if(value_count>=MAX_COLS){snprintf(err,errcap,"too many values");return -1;}snprintf(vals[value_count++],VALUE_LEN,"%s",tok[i++]);if(eq(tok[i],",")){i++;continue;}break;}if(i>=end||!eq(tok[i++],")")||i!=end||value_count!=input_count){snprintf(err,errcap,"number of columns and values do not match");return -1;}
 int rid;char*raw;if(allocate_page(&rid,&raw)!=0){snprintf(err,errcap,"could not allocate row page");return -1;}RowPage*r=(RowPage*)raw;r->magic=ROW_MAGIC;r->table_page=tid;r->next_row=-1;for(int k=0;k<value_count;k++)snprintf(r->values[mapping[k]],VALUE_LEN,"%.239s",vals[k]);buffer_mark_dirty(rid);buffer_unpin(rid);
 raw=buffer_get_page(tid);if(!raw){snprintf(err,errcap,"could not load table page");return -1;}TablePage*mt=(TablePage*)raw;if(mt->last_row<0)mt->first_row=rid;else{int last=mt->last_row;buffer_unpin(tid);raw=buffer_get_page(last);if(!raw){snprintf(err,errcap,"could not load last row");return -1;}((RowPage*)raw)->next_row=rid;buffer_mark_dirty(last);buffer_unpin(last);raw=buffer_get_page(tid);if(!raw){snprintf(err,errcap,"could not reload table page");return -1;}mt=(TablePage*)raw;}mt->last_row=rid;mt->row_count++;buffer_mark_dirty(tid);buffer_unpin(tid);return 0;}

static int parse_select_where(const SelectQuery*q,int*enabled,char*col,char*op,char*val){*enabled=q->where.enabled;if(!*enabled)return 0;snprintf(col,TOKEN_LEN,"%s",q->where.column);snprintf(op,3,"%s",q->where.op);snprintf(val,TOKEN_LEN,"%s",q->where.value);return 0;}
/* Portable insertion sort avoids non-standard qsort_r variants. */
static void sort_rows(ResultRow*rows,int n,int ci,int desc){for(int i=1;i<n;i++){ResultRow v=rows[i];int j=i-1;while(j>=0){int c=strcmp(rows[j].values[ci],v.values[ci]);if(desc)c=-c;if(c<=0)break;rows[j+1]=rows[j];j--;}rows[j+1]=v;}}
static int execute_select(char tok[][TOKEN_LEN],int n,char*out,int cap,int*used){SelectQuery q;if(parse_query(tok,n,&q)!=0)return appendf(out,cap,used,"ERR invalid SELECT syntax\nEND\n");int tid;TablePage t;if(table_find(q.table,&tid,&t)!=0)return appendf(out,cap,used,"ERR table does not exist\nEND\n");int where_on;char wc[TOKEN_LEN]="",wo[3]="",wv[TOKEN_LEN]="";parse_select_where(&q,&where_on,wc,wo,wv);if(where_on&&column_index(&t,wc)<0)return appendf(out,cap,used,"ERR unknown WHERE column\nEND\n");if(q.order.enabled&&column_index(&t,q.order.column)<0)return appendf(out,cap,used,"ERR unknown ORDER BY column\nEND\n");
 int has_agg=0,has_plain=0;if(!q.select_all)for(int e=0;e<q.expression_count;e++){if(q.expressions[e].type==EXPR_COLUMN)has_plain=1;else has_agg=1;if(q.expressions[e].type==EXPR_COLUMN&&column_index(&t,q.expressions[e].column)<0)return appendf(out,cap,used,"ERR unknown selected column\nEND\n");if(q.expressions[e].type!=EXPR_COUNT&&!q.expressions[e].star_argument&&column_index(&t,q.expressions[e].column)<0)return appendf(out,cap,used,"ERR unknown aggregate column\nEND\n");}if(has_agg&&has_plain)return appendf(out,cap,used,"ERR cannot mix aggregate and ordinary columns in this engine\nEND\n");if(q.order.enabled&&has_agg)return appendf(out,cap,used,"ERR ORDER BY with aggregate is not supported\nEND\n");
 ResultRow*rows=calloc(MAX_RESULT_ROWS,sizeof *rows);if(!rows)return appendf(out,cap,used,"ERR out of memory\nEND\n");int count=0,id=t.first_row,guard=0;while(id>=0&&guard++<MAX_RESULT_ROWS){char*raw=buffer_get_page(id);if(!raw){free(rows);return appendf(out,cap,used,"ERR could not read row page\nEND\n");}RowPage*r=(RowPage*)raw;if(r->magic!=ROW_MAGIC||r->table_page!=tid){buffer_unpin(id);free(rows);return appendf(out,cap,used,"ERR corrupt row page\nEND\n");}int match=row_matches(&t,r,where_on,wc,wo,wv);int next=r->next_row;if(match){if(count>=MAX_RESULT_ROWS){buffer_unpin(id);free(rows);return appendf(out,cap,used,"ERR result row limit exceeded\nEND\n");}rows[count].page_id=id;memcpy(rows[count].values,r->values,sizeof r->values);count++;}buffer_unpin(id);id=next;}
 if(guard>=MAX_RESULT_ROWS&&id>=0){free(rows);return appendf(out,cap,used,"ERR row-chain limit exceeded\nEND\n");}
 if(has_agg){if(appendf(out,cap,used,"OK\n")!=0){free(rows);return -1;}for(int e=0;e<q.expression_count;e++){SelectExpr*x=&q.expressions[e];if(e&&appendf(out,cap,used,"|")!=0){free(rows);return -1;}if(x->type==EXPR_COUNT){if(appendf(out,cap,used,"%d",count)!=0){free(rows);return -1;}}else{int ci=column_index(&t,x->column);double sum=0;int numeric_count=0;for(int r=0;r<count;r++){char*endp;double v=strtod(rows[r].values[ci],&endp);if(endp!=rows[r].values[ci]&&*endp=='\0'){sum+=v;numeric_count++;}}if(x->type==EXPR_SUM){if(appendf(out,cap,used,"%.10g",sum)!=0){free(rows);return -1;}}else{if(appendf(out,cap,used,"%.10g",numeric_count?sum/numeric_count:0.0)!=0){free(rows);return -1;}}}}if(appendf(out,cap,used,"\nEND\n")!=0){free(rows);return -1;}free(rows);return 0;}
 if(q.order.enabled){int ci=column_index(&t,q.order.column);sort_rows(rows,count,ci,q.order.descending);}
 if(appendf(out,cap,used,"OK\n")!=0){free(rows);return -1;}if(q.select_all){for(int c=0;c<t.column_count;c++){if(c&&appendf(out,cap,used,"|")!=0){free(rows);return -1;}if(appendf(out,cap,used,"%s",t.columns[c])!=0){free(rows);return -1;}}if(appendf(out,cap,used,"\n")!=0){free(rows);return -1;}}else{for(int e=0;e<q.expression_count;e++){if(e&&appendf(out,cap,used,"|")!=0){free(rows);return -1;}if(appendf(out,cap,used,"%s",q.expressions[e].column)!=0){free(rows);return -1;}}if(appendf(out,cap,used,"\n")!=0){free(rows);return -1;}}
 for(int r=0;r<count;r++){if(q.select_all){for(int c=0;c<t.column_count;c++){if(c&&appendf(out,cap,used,"|")!=0){free(rows);return -1;}if(appendf(out,cap,used,"%s",rows[r].values[c])!=0){free(rows);return -1;}}}else{for(int e=0;e<q.expression_count;e++){int ci=column_index(&t,q.expressions[e].column);if(e&&appendf(out,cap,used,"|")!=0){free(rows);return -1;}if(appendf(out,cap,used,"%s",rows[r].values[ci])!=0){free(rows);return -1;}}}if(appendf(out,cap,used,"\n")!=0){free(rows);return -1;}}
 if(appendf(out,cap,used,"END\n")!=0){free(rows);return -1;}free(rows);return 0;}

static int update_rows(char tok[][TOKEN_LEN],int n,char*err,size_t errcap){int end=next_statement_end(tok,n),i=0;if(end<6||!eq(tok[i++],"UPDATE")||i>=end||!is_identifier(tok[i])){snprintf(err,errcap,"syntax: UPDATE table SET column=value [WHERE column= value]");return -1;}int tid;TablePage t;if(table_find(tok[i++],&tid,&t)!=0){snprintf(err,errcap,"table does not exist");return -1;}if(i>=end||!eq(tok[i++],"SET")){snprintf(err,errcap,"expected SET");return -1;}int cols[MAX_COLS],nset=0;char vals[MAX_COLS][VALUE_LEN];while(i<end&&!eq(tok[i],"WHERE")){if(nset>=MAX_COLS||!is_identifier(tok[i])){snprintf(err,errcap,"invalid SET column");return -1;}cols[nset]=column_index(&t,tok[i++]);if(cols[nset]<0){snprintf(err,errcap,"unknown SET column");return -1;}if(i>=end||strcmp(tok[i++],"=")){snprintf(err,errcap,"expected = in SET");return -1;}if(i>=end){snprintf(err,errcap,"missing SET value");return -1;}snprintf(vals[nset],VALUE_LEN,"%.239s",tok[i++]);nset++;if(eq(tok[i],",")){i++;continue;}break;}if(nset==0){snprintf(err,errcap,"empty SET clause");return -1;}int where_on;char wc[TOKEN_LEN]="",wo[3]="",wv[TOKEN_LEN]="";if(parse_where_tokens(tok,end,&i,&where_on,wc,wo,wv)!=0||i!=end){snprintf(err,errcap,"invalid WHERE clause");return -1;}if(where_on&&column_index(&t,wc)<0){snprintf(err,errcap,"unknown WHERE column");return -1;}int id=t.first_row,changed=0,guard=0;while(id>=0&&guard++<MAX_RESULT_ROWS){char*raw=buffer_get_page(id);if(!raw){snprintf(err,errcap,"buffer pool full or page read failed");return -1;}RowPage*r=(RowPage*)raw;int next=r->next_row;if(row_matches(&t,r,where_on,wc,wo,wv)){for(int k=0;k<nset;k++)snprintf(r->values[cols[k]],VALUE_LEN,"%.239s",vals[k]);buffer_mark_dirty(id);changed++;}buffer_unpin(id);id=next;}if(id>=0){snprintf(err,errcap,"row-chain limit exceeded");return -1;}snprintf(err,errcap,"%d row(s) updated",changed);return 0;}

static int delete_rows(char tok[][TOKEN_LEN],int n,char*err,size_t errcap){int end=next_statement_end(tok,n),i=0;if(end<3||!eq(tok[i++],"DELETE")||!eq(tok[i++],"FROM")||i>=end||!is_identifier(tok[i])){snprintf(err,errcap,"syntax: DELETE FROM table [WHERE column operator value]");return -1;}int tid;TablePage t;if(table_find(tok[i++],&tid,&t)!=0){snprintf(err,errcap,"table does not exist");return -1;}int where_on;char wc[TOKEN_LEN]="",wo[3]="",wv[TOKEN_LEN]="";if(parse_where_tokens(tok,end,&i,&where_on,wc,wo,wv)!=0||i!=end){snprintf(err,errcap,"invalid WHERE clause");return -1;}if(where_on&&column_index(&t,wc)<0){snprintf(err,errcap,"unknown WHERE column");return -1;}int prev=-1,id=t.first_row,deleted=0,guard=0;while(id>=0&&guard++<MAX_RESULT_ROWS){char*raw=buffer_get_page(id);if(!raw){snprintf(err,errcap,"buffer pool full or page read failed");return -1;}RowPage*r=(RowPage*)raw;int next=r->next_row;int match=row_matches(&t,r,where_on,wc,wo,wv);buffer_unpin(id);if(match){if(prev<0){raw=buffer_get_page(tid);if(!raw){snprintf(err,errcap,"could not load table page");return -1;}TablePage*mt=(TablePage*)raw;mt->first_row=next;if(mt->last_row==id)mt->last_row=-1;mt->row_count--;buffer_mark_dirty(tid);buffer_unpin(tid);}else{raw=buffer_get_page(prev);if(!raw){snprintf(err,errcap,"could not load previous row");return -1;}((RowPage*)raw)->next_row=next;buffer_mark_dirty(prev);buffer_unpin(prev);raw=buffer_get_page(tid);if(!raw){snprintf(err,errcap,"could not load table page");return -1;}TablePage*mt=(TablePage*)raw;if(mt->last_row==id)mt->last_row=prev;mt->row_count--;buffer_mark_dirty(tid);buffer_unpin(tid);}deleted++;}else prev=id;id=next;}if(id>=0){snprintf(err,errcap,"row-chain limit exceeded");return -1;}snprintf(err,errcap,"%d row(s) deleted",deleted);return 0;}

int engine_open(const char*db_path){snprintf(database_path,sizeof database_path,"%s",db_path?db_path:"cyberdb.db");buffer_reset();if(storage_open(database_path)!=0)return -1;char walpath[600];snprintf(walpath,sizeof walpath,"%s.wal",database_path);txn_init(walpath);txn_recover();int pages=storage_page_count();if(pages<0){storage_close();return -1;}if(pages==0){int id=storage_alloc_page();if(id!=0){storage_close();return -1;}char*raw=buffer_get_page(0);if(!raw){storage_close();return -1;}memset(raw,0,PAGE_SIZE);((CatalogPage*)raw)->magic=CATALOG_MAGIC;((CatalogPage*)raw)->first_table=-1;buffer_mark_dirty(0);buffer_unpin(0);buffer_flush_all();}else{CatalogPage c;if(get_catalog(&c)!=0){storage_close();return -1;}}active_txn=0;return 0;}
void engine_close(void){if(active_txn){txn_rollback(active_txn);active_txn=0;}txn_checkpoint();storage_close();buffer_reset();}

int execute_sql(const char*sql,char*out_buf,int out_size){if(!sql||!out_buf||out_size<32)return -1;out_buf[0]=0;char tok[MAX_TOKENS][TOKEN_LEN];int n=tokenize_sql(sql,tok,MAX_TOKENS);if(n<0)return fail(out_buf,out_size,"tokenization failed or too many tokens");if(n==0)return fail(out_buf,out_size,"empty statement");int end=next_statement_end(tok,n);if(end==1&&(eq(tok[0],"EXIT")||eq(tok[0],"QUIT")))return fail(out_buf,out_size,"EXIT is a main-loop command");
 if(eq(tok[0],"BEGIN")){if(end!=1)return fail(out_buf,out_size,"syntax: BEGIN");if(active_txn)return fail(out_buf,out_size,"transaction already active");active_txn=txn_begin();snprintf(out_buf,(size_t)out_size,"OK\ntransaction=%d\nEND\n",active_txn);return 0;}
 if(eq(tok[0],"COMMIT")){if(end!=1)return fail(out_buf,out_size,"syntax: COMMIT");if(!active_txn)return fail(out_buf,out_size,"no active transaction");if(txn_commit(active_txn)!=0)return fail(out_buf,out_size,"commit failed; transaction remains active");active_txn=0;snprintf(out_buf,(size_t)out_size,"OK\ncommitted\nEND\n");return 0;}
 if(eq(tok[0],"ROLLBACK")){if(end!=1)return fail(out_buf,out_size,"syntax: ROLLBACK");if(!active_txn)return fail(out_buf,out_size,"no active transaction");txn_rollback(active_txn);active_txn=0;snprintf(out_buf,(size_t)out_size,"OK\nrolled back\nEND\n");return 0;}
 if(eq(tok[0],"SELECT")){int used=0;int rc=execute_select(tok,n,out_buf,out_size,&used);if(rc!=0&&out_buf[0]==0)return fail(out_buf,out_size,"output buffer too small");return rc;}
 int mutating=eq(tok[0],"CREATE")||eq(tok[0],"INSERT")||eq(tok[0],"UPDATE")||eq(tok[0],"DELETE");if(!mutating)return fail(out_buf,out_size,"unsupported statement");int own_txn=0;if(!active_txn){active_txn=txn_begin();own_txn=1;}char err[256]="statement failed";int rc;if(eq(tok[0],"CREATE"))rc=create_table(tok,n,err,sizeof err);else if(eq(tok[0],"INSERT"))rc=insert_row(tok,n,err,sizeof err);else if(eq(tok[0],"UPDATE"))rc=update_rows(tok,n,err,sizeof err);else rc=delete_rows(tok,n,err,sizeof err);
 if(rc!=0){txn_rollback(active_txn);active_txn=0;return fail(out_buf,out_size,err);}if(eq(tok[0],"CREATE"))snprintf(err,sizeof err,"table created");else if(eq(tok[0],"INSERT"))snprintf(err,sizeof err,"1 row inserted");if(own_txn){if(txn_commit(active_txn)!=0){txn_rollback(active_txn);active_txn=0;return fail(out_buf,out_size,"commit failed; changes rolled back in memory");}active_txn=0;}snprintf(out_buf,(size_t)out_size,"OK\n%s\nEND\n",err);return 0;}
